using System;using System.IO;using TCG.NativeCompatibility;
class Test {static int count;static void Eq(string a,string b){count++;if(a!=b)throw new Exception(a+" != "+b);}static void Main(string[] a){var dir=Path.Combine(Path.GetFullPath(a[0]),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var bundled=Path.Combine(dir,"bundle space");var search=Path.Combine(dir,"search space");Directory.CreateDirectory(bundled);Directory.CreateDirectory(search);File.WriteAllText(Path.Combine(bundled,"yt-dlp.exe"),"MZfake");File.WriteAllText(Path.Combine(search,"yt-dlp"),"#!/bin/sh\nexit 0\n");Eq(NativeToolPaths.Resolve(bundled,"yt-dlp.exe",false,search),Path.Combine(bundled,"yt-dlp.exe"));Eq(NativeToolPaths.Resolve(bundled,"yt-dlp.exe",true,search),Path.Combine(search,"yt-dlp"));File.WriteAllText(Path.Combine(bundled,"yt-dlp"),"#!/bin/sh\nexit 0\n");Eq(NativeToolPaths.Resolve(bundled,"yt-dlp.exe",true,search),Path.Combine(bundled,"yt-dlp"));Eq(NativeToolPaths.Resolve(bundled,"unknown.exe",true,search),Path.Combine(bundled,"unknown.exe"));foreach(var n in new[]{"qjs","ffmpeg"}){File.WriteAllText(Path.Combine(bundled,n),"#!/bin/sh\nexit 0\n");Eq(NativeToolPaths.Resolve(bundled,n+".exe",true,""),Path.Combine(bundled,n));}Eq(NativeToolPaths.Resolve(Path.Combine(dir,"missing"),"yt-dlp.exe",true,search),String.Empty);if(NativeToolPaths.IsMacExecutableFormat(Path.Combine(bundled,"yt-dlp.exe")))throw new Exception("PE accepted");if(NativeToolPaths.IsMac){if(!NativeToolPaths.CanSelfUpdate(Path.Combine(bundled,"yt-dlp"),bundled)||NativeToolPaths.CanSelfUpdate(Path.Combine(search,"yt-dlp"),bundled))throw new Exception("Self-update guard failed");count+=2;Eq(NativeToolPaths.FileManager(),"/usr/bin/open");}Console.WriteLine(count+" helper path tests passed; no helper executed");}}
